// rust-unsafe fixture: a three-package workspace. `safe` (no unsafe, not allowlisted), `ffi` (allowlisted, one
// documented unsafe block, one Miri-runnable test) and `app` (not allowlisted, path dependency on `ffi`: without
// clippy's --no-deps, ffi is linted with run A's flags and its unsafe is reported as RU2/RU3). Real pinned toolchains (rustup installs them: needs network).
// Defects: unsafe in `safe` (RU2), an expect of unsafe_code (RU2/E0453), a missing SAFETY comment (RU3), an allowlist
// naming a missing package (RU1), a deleted miri reference (RU4), an unreasoned entry (RU1).
import fs from 'node:fs';
import path from 'node:path';

const SAFE_LIB = `//! Fixture crate without unsafe.

/// Adds two numbers.
#[must_use]
pub fn add(a: u32, b: u32) -> u32 {
    a + b
}
`;

const FFI_LIB = `//! Fixture crate with one documented unsafe block.

/// Returns the byte at \`i\`, or \`None\` when out of range.
#[must_use]
pub fn get(xs: &[u8], i: usize) -> Option<u8> {
    if i < xs.len() {
        // SAFETY: \`i < xs.len()\` was checked on the line above.
        let x = unsafe { xs.get_unchecked(i) };
        Some(*x)
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::get;

    #[test]
    fn gets() {
        assert_eq!(get(&[1, 2, 3], 1), Some(2));
        assert_eq!(get(&[1, 2, 3], 3), None);
    }
}
`;

const APP_LIB = `//! Fixture crate that depends on the allowlisted \`ffi\`.

/// Reads the first byte.
#[must_use]
pub fn first(xs: &[u8]) -> Option<u8> {
    ffi::get(xs, 0)
}
`;

const ALLOW = '{ "ffi": { "reason": "fixture: bounds-checked get_unchecked" } }\n';
const SUITES = '{ "suites": [ { "id": "miri", "run": ["node", ".standards/rust-unsafe/unsafe.mjs", "miri"] } ] }\n';

export const fixture = {
  id: 'rust-unsafe',
  profiles: ['base@1.0.0', 'rust-base@1.0.0', 'rust-unsafe@1.0.1'],
  files: {
    '.gitignore': 'target/\n',
    'Cargo.toml': '[workspace]\nresolver = "2"\nmembers = ["safe", "ffi", "app"]\n',
    'Cargo.lock': '# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = "app"\nversion = "0.1.0"\ndependencies = [\n "ffi",\n]\n\n[[package]]\nname = "ffi"\nversion = "0.1.0"\n\n[[package]]\nname = "safe"\nversion = "0.1.0"\n',
    'safe/Cargo.toml': '[package]\nname = "safe"\nversion = "0.1.0"\nedition = "2021"\npublish = false\n',
    'safe/src/lib.rs': SAFE_LIB,
    'app/Cargo.toml': '[package]\nname = "app"\nversion = "0.1.0"\nedition = "2021"\npublish = false\n\n[dependencies]\nffi = { path = "../ffi" }\n',
    'app/src/lib.rs': APP_LIB,
    'ffi/Cargo.toml': '[package]\nname = "ffi"\nversion = "0.1.0"\nedition = "2021"\npublish = false\n',
    'ffi/src/lib.rs': FFI_LIB,
    'rust-unsafe.allow.json': ALLOW,
    'ci/suites.json': SUITES,
  },
  inject: (dir, h) => {
    const w = (rel, body) => fs.writeFileSync(path.join(dir, rel), body);
    const restore = () => {
      w('safe/src/lib.rs', SAFE_LIB);
      w('ffi/src/lib.rs', FFI_LIB);
      w('rust-unsafe.allow.json', ALLOW);
      w('ci/suites.json', SUITES);
    };
    const m = h.node(['.standards/rust-unsafe/unsafe.mjs', 'miri']);
    h.step(m.code === 0 && /1 test\(s\) executed under miri/.test(m.out), 'unsafe.mjs miri passes on the clean fixture and runs the test', `exit ${m.code}\n${m.out}`);
    const cases = [
      ['unsafe in a non-allowlisted package', () => w('safe/src/lib.rs', `${SAFE_LIB}\n/// Bad.\n#[must_use]\npub fn bad(x: &[u8]) -> u8 {\n    // SAFETY: fixture.\n    *unsafe { x.get_unchecked(0) }\n}\n`),
        (o) => /FAIL \[rust-unsafe\/RU2\] safe[\\/]src[\\/]lib\.rs:\d+/.test(o), 'fails RU2 naming safe/src/lib.rs'],
      ['an #[expect(unsafe_code)] in a non-allowlisted package', () => w('safe/src/lib.rs', `${SAFE_LIB}\n#[expect(unsafe_code, reason = "x")]\n/// Bad.\n#[must_use]\npub fn bad(x: &[u8]) -> u8 {\n    // SAFETY: fixture.\n    *unsafe { x.get_unchecked(0) }\n}\n`),
        (o) => /FAIL \[rust-unsafe\/RU2\] safe[\\/]src[\\/]lib\.rs:\d+: E0453/.test(o), 'fails RU2 with E0453'],
      ['a missing SAFETY comment in the allowlisted package', () => w('ffi/src/lib.rs', FFI_LIB.replace(/ {8}\/\/ SAFETY:.*\n/, '')),
        (o) => /FAIL \[rust-unsafe\/RU3\] ffi[\\/]src[\\/]lib.rs:7: clippy::undocumented_unsafe_blocks/.test(o), 'fails RU3 (undocumented_unsafe_blocks) naming ffi/src/lib.rs:7'],
      ['an allowlist naming a missing package', () => w('rust-unsafe.allow.json', '{ "ffi": { "reason": "x" }, "nope": { "reason": "x" } }\n'),
        (o) => /FAIL \[rust-unsafe\/RU1\] rust-unsafe\.allow\.json: "nope" is not a package/.test(o), 'fails RU1 naming "nope"'],
      ['an allowlist entry without a reason', () => w('rust-unsafe.allow.json', '{ "ffi": { "reason": "" } }\n'),
        (o) => /FAIL \[rust-unsafe\/RU1\] rust-unsafe\.allow\.json: "ffi" has an empty or missing reason/.test(o), 'fails RU1 on the empty reason'],
      ['a deleted miri reference', () => fs.rmSync(path.join(dir, 'ci', 'suites.json')),
        (o) => /FAIL \[rust-unsafe\/RU4\]/.test(o), 'fails RU4'],
    ];
    for (const [what, apply, ok, msg] of cases) {
      apply();
      const r = h.check();
      h.step(r.code === 1 && ok(r.out), `${what} ${msg}`, `exit ${r.code}\n${r.out}`);
      restore();
    }
    const again = h.check();
    h.step(again.code === 0, 'check.mjs passes again after the injections are removed', again.out);
  },
};
